update wvp_vlstream_firmware_task set deploy_status='CANCELLED',completed_at=#{completedAt},failure_reason=#{failureReason},update_time=#{completedAt}
where device_row_id=#{deviceRowId} and request_id=#{requestId}
and deploy_status in ('CREATED','PUBLISHED','ACCEPTED','DOWNLOADING','VERIFYING','INSTALLING','REBOOTING')
